"""Chromium with actual request wrapper and simulated fetch responses (no native service)."""
from pathlib import Path
import os,re
from playwright.sync_api import sync_playwright
src=Path(__file__).resolve().parents[1]/'src'
html=(src/'endpoint.html').read_text();html=re.sub(r'<script\b[^>]*>.*?</script>','',html,flags=re.S|re.I);html=re.sub(r'<link\b[^>]*>','',html,flags=re.I);html=html.replace('{{admin-hidden}}','').replace('{{brand}}','LinkScope').replace('{{version}}','V77');html=html.replace('</head>','<style>'+ '\n'.join((src/f).read_text() for f in ('app.css','theme.css','navigation.css','toast.css'))+'</style></head>')
js=(src/'app.js').read_text();js=js[:js.rindex('LinkScopeBusy.run(')]
toast=(src/'toast.js').read_text().split("    if(document.body.dataset.page==='login')return;",1)[0]+'})();'
base=dict(status='ok',engineOnline=True,engineRecoveryPending=False,signatureFreshness='Current',activeMalware=0,activeHeuristic=0,activeScanIssues=0,coverageIssueCount=0,violations=0,items=[],fullScanComplete=True,scanRunning=False,protectedPaths=[r'C:\Data'],rootCoverage=[dict(path=r'C:\Data',state='Watching',localWatcher=True)],pendingAlertDelivery=0,canaryCount=0,canaries=[],mode='monitor')
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),args=['--no-sandbox','--disable-dev-shm-usage','--disable-gpu']);page=browser.new_page(viewport={'width':1366,'height':768});page.set_default_timeout(6000);page.set_content(html);page.add_script_tag(content=toast);page.add_script_tag(content=js+'\nwindow.LinkScopePages={attach:()=>{}};csrf="test";maintenanceLast=Date.now();setupEndpointWorkspace();window.LinkScopeToast.individualRead=()=>{};window.LinkScopeToast.categoryRead=()=>{};')
 page.evaluate('''r=>{window.base=r;window.calls=[];window.reject=false;window.missing=false;window.records=[{id:'a',sequence:1,category:'endpoint_protection',severity:'warning',title:'USN journal coverage gap',message:'Historical unresolved path',resolved:false,read:false},{id:'b',sequence:2,category:'endpoint_protection',severity:'critical',title:'Malware signature detected',message:'Test verdict',resolved:false,read:false}];const counts=()=>({unread:records.filter(a=>!a.read).length,activeUnread:records.filter(a=>!a.read&&!a.resolved).length,through:Math.max(...records.map(a=>a.sequence))});window.fetch=async(path,options)=>{const response=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json'}});if(path==='/ui/endpoint-ack'&&options.method!=='POST')return response(counts());if(path==='/ui/endpoint'){const data={categories:{endpoint_protection:{result:{...base,activeMalware:records.some(a=>a.severity==='critical'&&!a.resolved)?1:0},ageSeconds:1,collectedUtc:'2026-11-28T07:00:00Z'}},generatedUtc:'2026-11-28T07:00:00Z'};if(!missing)data.alerts=records.filter(a=>!a.resolved);return response(data);}if(options.method==='POST'){if(options.headers['X-CSRF-Token']!=='test')throw Error('Missing CSRF');const data=JSON.parse(options.body);calls.push([path,data]);await new Promise(resolve=>setTimeout(resolve,450));if(path==='/ui/endpoint-alert-read'){records.find(a=>a.id===data.id).read=true;return response(counts());}if(path==='/ui/endpoint-alert-retry')return reject?response({error:'Verification cooldown active'},429):response({accepted:true,scope:'protected_paths'});}return response({},404);};}''',base)
 page.evaluate('renderHealth()');page.locator('[data-ep-tab=evidence]').click();page.locator('#endpoint-alert-diagnostics summary').click();rows=page.locator('#endpoint-alert-review-rows tbody tr');usn=rows.filter(has_text='USN journal coverage gap');mal=rows.filter(has_text='Malware signature detected');status=page.locator('#endpoint-alert-action-status');assert usn.locator('button').count()==3
 page.evaluate('window.poll77=setInterval(()=>renderHealth().catch(()=>{}),120)');usn.get_by_role('button',name='Acknowledge').click();usn.get_by_text('Acknowledged',exact=True).wait_for();assert status.get_attribute('data-state')=='success';assert rows.count()==2;assert mal.get_by_role('button',name='Acknowledge').count()==1
 usn.get_by_role('button',name='Retry verification').click();page.get_by_role('dialog').get_by_role('button',name='Retry verification').click();page.wait_for_function("document.getElementById('endpoint-alert-action-status').textContent.includes('Verification request accepted')");assert rows.count()==2
 page.evaluate('reject=true');usn.get_by_role('button',name='Retry verification').click();page.get_by_role('dialog').get_by_role('button',name='Retry verification').click();page.wait_for_function("document.getElementById('endpoint-alert-action-status').textContent.includes('Verification cooldown active')");assert status.get_attribute('data-state')=='error'
 page.evaluate('clearInterval(poll77)');page.wait_for_timeout(300)
 for theme in ['light','dark']:
  page.evaluate('t=>document.documentElement.dataset.theme=t',theme)
  for width in [390,768,1366]:
   page.set_viewport_size({'width':width,'height':800});assert page.evaluate('document.documentElement.scrollWidth <= innerWidth+1'),(theme,width)
   assert usn.evaluate("r=>[...r.querySelectorAll('.ep-alert-actions button')].every(b=>{const x=b.getBoundingClientRect(),p=b.parentElement.getBoundingClientRect();return x.left>=p.left-1&&x.right<=p.right+1&&x.height>=30})"),(theme,width)
 page.evaluate("records.push({...records[0],id:'c',sequence:3,read:false,message:'New distinct occurrence'});renderHealth()");assert rows.count()==3;assert rows.filter(has_text='New distinct occurrence').get_by_role('button',name='Acknowledge').count()==1
 page.evaluate('missing=true;renderHealth()');assert rows.count()==3;assert 'missing' in page.locator('#endpoint-alert-review-freshness').inner_text();page.evaluate('missing=false;renderHealth()')
 page.locator('[data-ep-tab=overview]').click();assert page.locator('#ep-overview').get_attribute('data-state')=='fail'
 page.evaluate('endpointOverview({result:base,ageSeconds:1},[])');assert page.locator('#ep-overview').get_attribute('data-state')=='ok'
 page.evaluate('endpointOverview({result:{...base,status:"scanning",scanRunning:true,fullScanComplete:false},ageSeconds:1},[])');assert page.locator('#ep-overview').get_attribute('data-state')=='verifying'
 page.evaluate('endpointOverview({result:base,ageSeconds:1},[{severity:"warning",title:"USN journal coverage gap",resolved:false,read:true}])');assert page.locator('#ep-overview').get_attribute('data-state')=='review'
 page.evaluate('endpointOverview({result:{...base,pendingAlertDelivery:1},ageSeconds:1},[])');assert page.locator('#ep-overview').get_attribute('data-state')=='review'
 page.evaluate('endpointOverview({result:base,ageSeconds:1},null)');assert page.locator('#ep-overview').get_attribute('data-state')!='ok'
 page.evaluate('endpointOverview({result:{...base,activeMalware:1},ageSeconds:1},[])');assert page.locator('#ep-overview').get_attribute('data-state')=='fail'
 page.evaluate('endpointOverview({result:base,ageSeconds:31},[])');assert page.locator('#ep-overview').get_attribute('data-state')=='unknown'
 assert page.evaluate('calls')==[['/ui/endpoint-alert-read',{'id':'a'}],['/ui/endpoint-alert-retry',{'id':'a'}],['/ui/endpoint-alert-retry',{'id':'a'}]]
 browser.close()
print('PASS: actual browser request wrapper with simulated delayed and rejected fetch responses, stable rows during polling, responsive actions, new unread incident, missing alert evidence and verified/neutral/amber/red/stale overview.')
